import{_ as s,o as e,c as i,a4 as o}from"./chunks/framework.BBs01uty.js";const k=JSON.parse('{"title":"测试策略与基础设施","description":"","frontmatter":{},"headers":[],"relativePath":"agent-cli/testing.md","filePath":"agent-cli/testing.md"}'),a={name:"agent-cli/testing.md"};function d(n,t,r,c,l,h){return e(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="测试策略与基础设施" tabindex="-1">测试策略与基础设施 <a class="header-anchor" href="#测试策略与基础设施" aria-label="Permalink to &quot;测试策略与基础设施&quot;">​</a></h1><blockquote><p>本项目 <strong>测试代码 14,687 行 &gt; 生产代码 12,131 行</strong>。这不是偶然：TUI 的正确性没法靠肉眼验证， &quot;测试即规格&quot; 也是各模块能被放心重构的前提。</p></blockquote><h2 id="_1-三层验证体系" tabindex="-1">1. 三层验证体系 <a class="header-anchor" href="#_1-三层验证体系" aria-label="Permalink to &quot;1. 三层验证体系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>手段</th><th>覆盖什么</th><th>举例</th></tr></thead><tbody><tr><td>纯逻辑单测</td><td>Vitest 直测</td><td>不碰 stdin/stdout 的模块（分层铁律保证了它们可测）</td><td><code>status-machine</code> 迁移表穷举、<code>truncate</code> 口径、<code>permissions</code> 判定表</td></tr><tr><td><strong>UI 端到端</strong></td><td><code>term-sim</code> 终端模拟器驱动真实 <code>TUI</code></td><td><strong>交互流程</strong>与&quot;终端画面&quot;：流式渲染、浮层、按键、resize、退出</td><td><code>tui.e2e.test.ts</code>（2642 行）、<code>index.e2e.test.ts</code></td></tr><tr><td>真实子进程 / 真实 fs</td><td>真 spawn / 真写盘 + <code>ps</code> 复核</td><td>进程组回收、日志落盘、原子写、信任写盘</td><td><code>tasks.test.ts</code>、<code>project-permissions.test.ts</code></td></tr></tbody></table><p>真实 PTY（起 dist 进程手敲）只作<strong>手动冒烟</strong>，不进常规测试（慢、断言繁琐）。</p><h2 id="_2-怎么跑" tabindex="-1">2. 怎么跑 <a class="header-anchor" href="#_2-怎么跑" aria-label="Permalink to &quot;2. 怎么跑&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # vitest run（35 文件 / 900+ 用例）</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --noEmit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 类型检查</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # tsc 编译到 dist/</span></span></code></pre></div><p><strong>harness verify 通道</strong>（工作流阶段 gate 只认它）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .harness/tools/verify.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .harness/workspace/{task-id}/test-results</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --report</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .harness/workspace/{task-id}/verify/verification-result.json</span></span></code></pre></div><p>命令来自 <code>knowledge/verify.config.json</code>（<code>build</code> + <code>test</code>），<strong>不允许命令行自选</strong>（他证原则）； 证据落盘 <code>verification-result.json</code>，gate 校验只认 <code>overall_status: passed</code>。</p><h2 id="_3-term-sim-终端模拟器-src-testing-term-sim-ts" tabindex="-1">3. <code>term-sim</code> 终端模拟器（<code>src/testing/term-sim.ts</code>） <a class="header-anchor" href="#_3-term-sim-终端模拟器-src-testing-term-sim-ts" aria-label="Permalink to &quot;3. `term-sim` 终端模拟器（`src/testing/term-sim.ts`）&quot;">​</a></h2><p>进程内驱动真实 <code>TUI</code> 并断言&quot;终端画面&quot;：</p><ul><li>解析 CSI：光标定位（CUP/CHA）、erase、<strong>DECSTBM 滚动区</strong>、清屏 / 清历史；</li><li>维护<strong>屏幕字符矩阵 + 滚动历史（scrollback）</strong>，支持 resize；</li><li>宽字符（中文 2 列，第二列占位符自动去除，断言无假空格）、wrap-pending、滚动区滚动。</li></ul><p>夹具方式（<code>tui.e2e.test.ts</code> 的 beforeEach）：<code>process.stdout.write</code> 喂给 TermSim； stdin 用 EventEmitter 模拟 keypress（<code>press()</code> / <code>type()</code> 辅助函数）。</p><h3 id="模拟器注意点-踩过的坑" tabindex="-1">模拟器注意点（踩过的坑） <a class="header-anchor" href="#模拟器注意点-踩过的坑" aria-label="Permalink to &quot;模拟器注意点（踩过的坑）&quot;">​</a></h3><ol><li><strong>resize</strong>：先 <code>term.resize()</code> 扩展屏幕，再触发 <code>onResize</code>（不要用滚动区指令推断行数）。</li><li><code>\\x1b[3J</code> 清滚动历史 —— 断言 scrollback 时注意它。</li><li><strong>键名</strong>：Enter 的 <code>name</code> 在真实 PTY 下可能是 <code>enter</code> 也可能是 <code>return</code>（Ctrl+J 是 <code>name:&#39;enter&#39;</code>）——断言/模拟都要兼容。<code>/</code> 这类符号键 <strong><code>name === undefined</code></strong>。</li><li><strong>TermSim 只解析部分 CSI（<code>H/G/K/J/r</code>），SGR（颜色）会被吞</strong> —— 要断言颜色 / 不可见序列（如 bracketed paste、OSC），得看测试收集的 <code>rawWrites</code>（原始写入串）。</li><li><strong>断言要&quot;精确 + 负向&quot;</strong>：<code>toContain(&#39;| !&#39;)</code> 对 <code>| ! echo</code> 和 <code>| ! !echo</code> 都通过，会<strong>把 bug 锁成预期</strong>（真实案例）。用精确串 + <code>not.toContain(重复特征)</code>。</li></ol><h2 id="_4-故障注入反证-lesson-017-021" tabindex="-1">4. 故障注入反证（lesson 017/021） <a class="header-anchor" href="#_4-故障注入反证-lesson-017-021" aria-label="Permalink to &quot;4. 故障注入反证（lesson 017/021）&quot;">​</a></h2><p>&quot;全绿&quot;不等于真实路径可用。关键 AC 用<strong>反证用例</strong>锁死 —— 把实现改坏，测试必须变红：</p><table tabindex="0"><thead><tr><th>AC</th><th>反证方式</th></tr></thead><tbody><tr><td>AC-8（高度恒定）</td><td>高度若误用&quot;当前页选项数&quot;则 FAIL</td></tr><tr><td>AC-18（单一形状）</td><td>两条仅 <code>kind</code> 不同的条目必须逐字相同 + 代码检索&quot;渲染无 <code>kind</code> 分支&quot;</td></tr><tr><td>AC-51（forced 不变式）</td><td>把 store 提到 <code>forced</code> 之前判定 → FAIL</td></tr><tr><td>AC-41（definitions 基线）</td><td>与重构前序列化快照比对（sha256）</td></tr><tr><td>AC-59（前缀稳定性）</td><td>连续两轮请求 system+tools 字节逐字一致</td></tr></tbody></table><p>新增关键行为时问自己：<strong>&quot;如果有人把它改坏，哪条测试会红？&quot;</strong> 答不上来就补一条。</p><h2 id="_5-生产接线也要锁-lesson-021-能力可达性" tabindex="-1">5. 生产接线也要锁（lesson 021 / 能力可达性） <a class="header-anchor" href="#_5-生产接线也要锁-lesson-021-能力可达性" aria-label="Permalink to &quot;5. 生产接线也要锁（lesson 021 / 能力可达性）&quot;">​</a></h2><p>&quot;方法有单测&quot; ≠ &quot;生产真的调用了它&quot;。对<strong>接线</strong>类改动，补结构断言（读源码 grep，如 <code>index.ts</code> 的 <code>onChange</code> 必须含 <code>refreshTaskPanel</code>、<code>openSelector</code> 必须无调用点）。</p><h2 id="_6-文档漂移检查-防腐烂" tabindex="-1">6. 文档漂移检查（防腐烂） <a class="header-anchor" href="#_6-文档漂移检查-防腐烂" aria-label="Permalink to &quot;6. 文档漂移检查（防腐烂）&quot;">​</a></h2><p><code>docs/modules.md</code> 的模块清单与 <code>src/</code> 实际文件<strong>必须一致</strong>。检查脚本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/check-drift.mjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 比对文档清单 vs find src -name &#39;*.ts&#39;，不一致 exit 1</span></span></code></pre></div><p>（清单以 <code>modules.md</code> 中 <code>`[模块相对路径]`</code> 的反引号链接为准；新增 / 删除源文件后同步更新并跑一次。）</p>',26)])])}const g=s(a,[["render",d]]);export{k as __pageData,g as default};
